package kr.or.arte.seal.delivery.application;
import kr.or.arte.seal.audit.application.*;import kr.or.arte.seal.link.application.*;import kr.or.arte.seal.recipient.application.*;import kr.or.arte.seal.recipient.crypto.*;import kr.or.arte.seal.request.application.*;import kr.or.arte.seal.request.domain.ConsentRequestStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;
@Service public class ConsentDeliveryService{private final ConsentRequestRepository requests;private final SecureLinkManagementService links;private final RecipientDeliveryContactQuery contacts;private final ConsentMailRenderer renderer;private final PersonalDataCipher cipher;private final MailOutboxRepository outbox;private final AuditEventWriter audit;private final Clock clock;
 public ConsentDeliveryService(ConsentRequestRepository r,SecureLinkManagementService l,RecipientDeliveryContactQuery c,ConsentMailRenderer renderer,PersonalDataCipher cipher,MailOutboxRepository o,AuditEventWriter a,Clock clock){requests=r;links=l;contacts=c;this.renderer=renderer;this.cipher=cipher;outbox=o;audit=a;this.clock=clock;}
 @Transactional public DeliveryIssueResult activateAndQueue(UUID actor,UUID requestId,long version,String baseUrl,Instant scheduled){var request=requests.findScopedForUpdate(actor,requestId).orElseThrow(RequestNotFoundException::new);if(request.status()!=ConsentRequestStatus.READY)throw new RequestBusinessConflictException("발송 준비 상태의 요청만 발송할 수 있습니다.");var issued=links.activate(actor,requestId,version);return queue(actor,request,issued,baseUrl,scheduled);}
 @Transactional public DeliveryIssueResult reissueAndQueue(UUID actor,UUID requestId,long version,String baseUrl,Instant scheduled){var request=requests.findScopedForUpdate(actor,requestId).orElseThrow(RequestNotFoundException::new);if(request.status()!=ConsentRequestStatus.ACTIVE)throw new RequestBusinessConflictException("진행 중인 요청만 재발송할 수 있습니다.");outbox.cancelPending(requestId,clock.instant());var issued=links.reissue(actor,requestId,version);return queue(actor,request,issued,baseUrl,scheduled);}
 private DeliveryIssueResult queue(UUID actor,ConsentRequestRecord request,IssuedSecureLink issued,String baseUrl,Instant scheduled){var contact=contacts.find(actor,request.recipientId());String snapshot=requests.findSnapshotJsonScoped(actor,request.requestId()).orElseThrow(RequestNotFoundException::new);String url=baseUrl.replaceAll("/$","")+"/consent/"+issued.token();var mail=renderer.render(snapshot,contact.name(),url);UUID id=UUID.randomUUID();var email=cipher.encrypt(new PersonalDataContext("MAIL_OUTBOX",id,request.organizationUnitId(),"recipientEmail"),contact.email());var html=cipher.encrypt(new PersonalDataContext("MAIL_OUTBOX",id,request.organizationUnitId(),"html"),mail.html());Instant now=clock.instant();Instant sendAt=scheduled==null||scheduled.isBefore(now)?now:scheduled;var row=new MailOutboxRecord(id,request.requestId(),Objects.requireNonNull(issued.linkId()),request.organizationUnitId(),email.bytes(),html.bytes(),email.keyId(),mail.subject(),mail.sha256(),MailOutboxStatus.QUEUED,sendAt,sendAt,0,null,0);
  outbox.insert(row,actor,now);audit.append(new AuditEventCommand(now,"ADMIN",actor,"MAIL_OUTBOX_CREATE","MAIL_OUTBOX",id.toString(),"SUCCESS",null,UUID.randomUUID(),Map.of("requestId",request.requestId().toString(),"status","QUEUED")));return new DeliveryIssueResult(id,issued,MailOutboxStatus.QUEUED);}
}
